def main():
    n = int(input())
    arr = list(map(int,input().split()))

    # calculate the number of j for each i that satisfy arr[max(i,j)] - arr[min(i,j)] >= target
    def measurecount(arr,target):
        m = len(arr)
        count = [0]*m
        minimum = []
        for i in range(m):
            for j in range(len(minimum)):
                if minimum[j] + target <= arr[i]:
                    count[i] += 1
            minimum.append(arr[i])
            minimum.sort()
            if len(minimum) > 3:
                minimum.pop()
        maximum = []
        for i in range(m-1,-1,-1):
            for j in range(len(maximum)):
                if maximum[j] - target >= arr[i]:
                    count[i] += 1
            maximum.append(arr[i])
            maximum.sort(reverse=True)
            if len(maximum) > 3:
                maximum.pop()
        return count

    # binary search to judge if we can find such pair
    def judge(target):
        count = measurecount(arr,target)
        if max(count) <= 1:
            return False
        pick = []
        if max(count) > 2:
            for i in range(n):
                if count[i] > 2:
                    pick = [i]
                    break
        else:
            for i in range(n):
                if count[i] != 2: 
                    continue 
                for j in range(n):
                    if j==i: 
                        pick.append(j)
                    elif j < i and arr[j] + target <= arr[i]: 
                        pick.append(j)
                    elif j > i and arr[i] + target <= arr[j]:
                        pick.append(j)
                break

        for p in pick:
            count2 = measurecount(arr[:p]+arr[p+1:], target)
            if max(count2) <= 1:
                return False
        return True       

    front = -10**9 - 10
    rear = 10**9 + 10
    while front < rear:
        mid = front + (rear-front)//2
        res = judge(mid)
        if res:
            front = mid + 1
        else:
            rear = mid 
    ans = front - 1
    print(ans)

